// Regenerates src/app/data/recruitment.ts so it imports every JSON file in src/app/data/recruitment.
// Runs before start, build, test and watch, so dropping in a new unit's file is all that's needed.
const fs = require('fs');
const path = require('path');

const DIR = path.join(__dirname, '..', 'src', 'app', 'data', 'recruitment');
const OUT = path.join(__dirname, '..', 'src', 'app', 'data', 'recruitment.ts');

const files = fs
  .readdirSync(DIR)
  .filter((name) => name.toLowerCase().endsWith('.json'))
  .sort((a, b) => a.localeCompare(b));

const lines = [
  '// Generated by tools/build-recruitment-index.js from the files in ./recruitment; do not edit.',
  ...files.map((name, i) => `import file${i} from './recruitment/${name}';`),
  '',
  'export const RECRUITMENT_FILES: readonly unknown[] = [',
  ...files.map((_, i) => `  file${i},`),
  '];',
  '',
];

const next = lines.join('\n');
const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';

if (current !== next) {
  fs.writeFileSync(OUT, next, 'utf8');
}

console.log(`Recruitment index: ${files.length} unit file(s).`);
